        eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   schoolInfo: () => (/* binding */ schoolInfo)\n/* harmony export */ });\nconst schoolInfo = {\n    npsn: '40300132',\n    name: 'SD Negeri 32 Bawasalo',\n    officialName: 'UPTD SD Negeri 32 Bawasalo',\n    status: 'Negeri',\n    accreditation: 'Terakreditasi B',\n    accreditationGrade: 'B (Baik)',\n    foundedYear: '1982',\n    principal: {\n        name: 'Abu Bakar , S.Pd., M.Pd.',\n        nip: '197105121993072001',\n        photoUrl: 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&q=80&w=600',\n        greeting: 'Assalamu Alaikum Warahmatullahi Wabarakatuh, Tabee maremma. Selamat datang di portal resmi UPTD SD Negeri 32 Bawasalo. Kami berkomitmen mewujudkan generasi cerdas, berkarakter luhur, berwawasan lingkungan, serta menjunjung tinggi nilai budaya kearifan lokal Sipakatau, Sipakalebbi, dan Sipakainge di Kabupaten Pangkajene dan Kepulauan.'\n    },\n    address: {\n        street: 'Jl. Poros Bawasalo - Segeri No. 32',\n        village: 'Kelurahan Bawasalo',\n        district: 'Kecamatan Segeri',\n        regency: 'Kabupaten Pangkajene dan Kepulauan',\n        province: 'Sulawesi Selatan',\n        postalCode: '90652',\n        fullAddress: 'Kelurahan Bawasalo, Kecamatan Segeri, Kabupaten Pangkajene dan Kepulauan, Sulawesi Selatan 90652'\n    },\n    contact: {\n        phone: '(0410) 2311-032',\n        email: 'sdn32bawasalo.segeri@gmail.com',\n        whatsappHotline: '6285299256705',\n        whatsappNumberOnly: '6285299256705',\n        operationalHours: 'Senin - Sabtu: 07.15 - 13.00 WITA'\n    },\n    stats: {\n        totalStudents: 184,\n        totalTeachers: 14,\n        totalClasses: 6,\n        totalRombel: 6\n    },\n    vision: 'Terwujudnya Peserta Didik yang Beriman dan Bertaqwa, Berakhlak Mulia, Cerdas, Terampil, serta Berakar pada Budaya Bangsa dan Peduli Lingkungan.',\n    missions: [\n        'Menanamkan nilai-nilai keimanan, ketaqwaan, dan budi pekerti luhur melalui pembiasaan ibadah dan keteladanan.',\n        'Melaksanakan proses pembelajaran Kurikulum Merdeka yang aktif, kreatif, inovatif, dan menyenangkan (Joyful Learning).',\n        'Menumbuhkembangkan bakat, minat, dan potensi peserta didik dalam bidang akademik, seni budaya lokal, dan olahraga.',\n        'Menerapkan nilai-nilai kearifan lokal Bugis-Makassar: Sipakatau (saling memanusiakan), Sipakalebbi (saling menghargai), dan Sipakainge (saling mengingatkan).',\n        'Membina kemandirian peserta didik melalui kegiatan kepramukaan, usaha kesehatan sekolah (UKS), dan kepedulian lingkungan hidup.'\n    ],\n    goals: [\n        'Mempersiapkan lulusan yang berkarakter kuat, berprestasi akademik, dan siap melanjutkan ke jenjang SMP/sederajat.',\n        'Meningkatkan kompetensi literasi dan numerasi seluruh siswa sesuai standar Asesmen Nasional (ANBK).',\n        'Mengikutsertakan siswa dalam ajang kompetisi O2SN, FLS2N, dan KSN tingkat kecamatan maupun kabupaten Pangkep.',\n        'Menciptakan lingkungan sekolah yang bersih, hijau, aman, dan ramah anak (Adiwiyata Tingkat Kabupaten).'\n    ],\n    coreValues: [\n        {\n            title: 'Saling Menghargai & Memanusiakan',\n            localTerm: 'Sipakatau',\n            description: 'Menjunjung tinggi martabat setiap warga sekolah tanpa membedakan latar belakang, menumbuhkan empati dan kerukunan.'\n        },\n        {\n            title: 'Saling Memuliakan & Mengapresiasi',\n            localTerm: 'Sipakalebbi',\n            description: 'Membiasakan tutur kata sopan santun (tabe\\') dan senantiasa menghargai setiap usaha serta prestasi yang dicapai siswa.'\n        },\n        {\n            title: 'Saling Mengingatkan dalam Kebaikan',\n            localTerm: 'Sipakainge',\n            description: 'Membangun budaya gotong royong dan kedisiplinan dengan saling mengingatkan terhadap tanggung jawab dan kebenaran.'\n        }\n    ]\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/data/school-info.ts\n");

